type Style struct {
	Hide        *bool   `yaml:"hide"`
	Bold        *bool   `yaml:"bold"`
	Faint       *bool   `yaml:"faint"`
	Italic      *bool   `yaml:"italic"`
	Underline   *bool   `yaml:"underline"`
	BlinkSlow   *bool   `yaml:"blinkSlow"`
	BlinkRapid  *bool   `yaml:"blinkRapid"`
	Inverse     *bool   `yaml:"inverse"`
	Conceal     *bool   `yaml:"conceal"`
	CrossOut    *bool   `yaml:"crossOut"`
	Frame       *bool   `yaml:"frame"`
	Encircle    *bool   `yaml:"encircle"`
	Overline    *bool   `yaml:"overline"`
	Foreground  string  `yaml:"foreground"`
	Background  string  `yaml:"background"`
}

type Config struct {
	LabelType        string   `yaml:"labelType"`
	BuildStyle       Style    `yaml:"buildStyle"`
	StartStyle       Style    `yaml:"startStyle"`
	PassStyle        Style    `yaml:"passStyle"`
	FailStyle        Style    `yaml:"failStyle"`
	SkipStyle        Style    `yaml:"skipStyle"`
	FileStyle        Style    `yaml:"fileStyle"`
	LineStyle        Style    `yaml:"lineStyle"`
	PassPackageStyle Style    `yaml:"passPackageStyle"`
	FailPackageStyle Style    `yaml:"failPackageStyle"`
	CoverThreshold   int      `yaml:"coverThreshold"`
	CoveredStyle     Style    `yaml:"coveredStyle"`
	UncoveredStyle   Style    `yaml:"uncoveredStyle"`
	Removals         []string `yaml:"removals"`
	LeaveTestPrefix  bool     `yaml:"leaveTestPrefix"`
}

func defaultStyle() Config {
	return Config{
		LabelType: "long",
		BuildStyle: Style{
			Bold:       ptr(true),
			Foreground: "yellow",
		},
		StartStyle: Style{
			Foreground: "lightBlack",
		},
		PassStyle: Style{
			Foreground: "green",
		},
		FailStyle: Style{
			Bold:       ptr(true),
			Foreground: "red",
		},
		SkipStyle: Style{
			Foreground: "lightBlack",
		},
		PassPackageStyle: Style{
			Foreground: "green",
			Hide:       ptr(true),
		},
		FailPackageStyle: Style{
			Bold:       ptr(true),
			Foreground: "red",
			Hide:       ptr(true),
		},
		CoverThreshold: 50,
		CoveredStyle: Style{
			Foreground: "green",
		},
		UncoveredStyle: Style{
			Bold:       ptr(true),
			Foreground: "yellow",
		},
		FileStyle: Style{
			Foreground: "cyan",
		},
		LineStyle: Style{
			Foreground: "magenta",
		},
	}
}

func ptr[T any](v T) *T {
	return &v
}

func mergeStyle(base, overlay Style) Style {
	if overlay.Hide != nil {
		base.Hide = overlay.Hide
	}
	if overlay.Bold != nil {
		base.Bold = overlay.Bold
	}
	if overlay.Faint != nil {
		base.Faint = overlay.Faint
	}
	if overlay.Italic != nil {
		base.Italic = overlay.Italic
	}
	if overlay.Underline != nil {
		base.Underline = overlay.Underline
	}
	if overlay.BlinkSlow != nil {
		base.BlinkSlow = overlay.BlinkSlow
	}
	if overlay.BlinkRapid != nil {
		base.BlinkRapid = overlay.BlinkRapid
	}
	if overlay.Inverse != nil {
		base.Inverse = overlay.Inverse
	}
	if overlay.Conceal != nil {
		base.Conceal = overlay.Conceal
	}
	if overlay.CrossOut != nil {
		base.CrossOut = overlay.CrossOut
	}
	if overlay.Frame != nil {
		base.Frame = overlay.Frame
	}
	if overlay.Encircle != nil {
		base.Encircle = overlay.Encircle
	}
	if overlay.Overline != nil {
		base.Overline = overlay.Overline
	}
	if overlay.Foreground != "" {
		base.Foreground = overlay.Foreground
	}
	if overlay.Background != "" {
		base.Background = overlay.Background
	}
	return base
}

func mergeConfig(base, overlay Config) Config {
	if overlay.LabelType != "" {
		base.LabelType = overlay.LabelType
	}
	base.BuildStyle = mergeStyle(base.BuildStyle, overlay.BuildStyle)
	base.StartStyle = mergeStyle(base.StartStyle, overlay.StartStyle)
	base.PassStyle = mergeStyle(base.PassStyle, overlay.PassStyle)
	base.FailStyle = mergeStyle(base.FailStyle, overlay.FailStyle)
	base.SkipStyle = mergeStyle(base.SkipStyle, overlay.SkipStyle)
	base.FileStyle = mergeStyle(base.FileStyle, overlay.FileStyle)
	base.LineStyle = mergeStyle(base.LineStyle, overlay.LineStyle)
	base.PassPackageStyle = mergeStyle(base.PassPackageStyle, overlay.PassPackageStyle)
	base.FailPackageStyle = mergeStyle(base.FailPackageStyle, overlay.FailPackageStyle)
	if overlay.CoverThreshold != 0 {
		base.CoverThreshold = overlay.CoverThreshold
	}
	base.CoveredStyle = mergeStyle(base.CoveredStyle, overlay.CoveredStyle)
	base.UncoveredStyle = mergeStyle(base.UncoveredStyle, overlay.UncoveredStyle)
	if overlay.Removals != nil {
		base.Removals = append(base.Removals, overlay.Removals...)
	}
	if overlay.LeaveTestPrefix {
		base.LeaveTestPrefix = true
	}
	return base
}

func colorToAnsi(color string, isBackground bool) string {
	if color == "" {
		return ""
	}
	offset := 0
	if isBackground {
		offset = 10
	}

	switch strings.ToLower(color) {
	case "black":
		return fmt.Sprintf("%d", 30+offset)
	case "red":
		return fmt.Sprintf("%d", 31+offset)
	case "green":
		return fmt.Sprintf("%d", 32+offset)
	case "yellow":
		return fmt.Sprintf("%d", 33+offset)
	case "blue":
		return fmt.Sprintf("%d", 34+offset)
	case "magenta":
		return fmt.Sprintf("%d", 35+offset)
	case "cyan":
		return fmt.Sprintf("%d", 36+offset)
	case "white":
		return fmt.Sprintf("%d", 37+offset)
	case "lightblack":
		return fmt.Sprintf("%d", 90+offset)
	case "lightred":
		return fmt.Sprintf("%d", 91+offset)
	case "lightgreen":
		return fmt.Sprintf("%d", 92+offset)
	case "lightyellow":
		return fmt.Sprintf("%d", 93+offset)
	case "lightblue":
		return fmt.Sprintf("%d", 94+offset)
	case "lightmagenta":
		return fmt.Sprintf("%d", 95+offset)
	case "lightcyan":
		return fmt.Sprintf("%d", 96+offset)
	case "lightwhite":
		return fmt.Sprintf("%d", 97+offset)
	}

	if strings.HasPrefix(color, "#") {
		var r, g, b uint8
		fmt.Sscanf(color, "#%02x%02x%02x", &r, &g, &b)
		return fmt.Sprintf("%d;2;%d;%d;%d", 38+offset, r, g, b)
	}

	if strings.HasPrefix(color, "rgb(") {
		var r, g, b int
		if _, err := fmt.Sscanf(color, "rgb(%d,%d,%d)", &r, &g, &b); err == nil {
			return fmt.Sprintf("%d;2;%d;%d;%d", 38+offset, r, g, b)
		}
	}

	return ""
}

func (s Style) ToAnsi() string {
	var parts []string
	if s.Bold != nil && *s.Bold {
		parts = append(parts, "1")
	}
	if s.Faint != nil && *s.Faint {
		parts = append(parts, "2")
	}
	if s.Italic != nil && *s.Italic {
		parts = append(parts, "3")
	}
	if s.Underline != nil && *s.Underline {
		parts = append(parts, "4")
	}
	if s.BlinkSlow != nil && *s.BlinkSlow {
		parts = append(parts, "5")
	}
	if s.BlinkRapid != nil && *s.BlinkRapid {
		parts = append(parts, "6")
	}
	if s.Inverse != nil && *s.Inverse {
		parts = append(parts, "7")
	}
	if s.Conceal != nil && *s.Conceal {
		parts = append(parts, "8")
	}
	if s.CrossOut != nil && *s.CrossOut {
		parts = append(parts, "9")
	}

	if fg := colorToAnsi(s.Foreground, false); fg != "" {
		parts = append(parts, fg)
	}
	if bg := colorToAnsi(s.Background, true); bg != "" {
		parts = append(parts, bg)
	}

	if len(parts) == 0 {
		return ""
	}
	return "\x1b[" + strings.Join(parts, ";") + "m"
}

func applyStyle(text string, style Style) string {
	ansi := style.ToAnsi()
	if ansi == "" {
		return text
	}
	return ansi + text + "\x1b[0m"
}

func main() {
	if len(os.Args) > 1 && os.Args[1] == "testfilter" {
		runFilter()
		return
	}

	if len(os.Args) > 1 && os.Args[1] == "test" {
		runTest(os.Args[2:])
		return
	}

	// Default: delegate to go
	cmd := exec.Command("go", os.Args[1:]...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}

func loadConfig() Config {
	cfg := defaultStyle()

	paths := []string{}
	cwd, _ := os.Getwd()
	paths = append(paths, fmt.Sprintf("%s/.richstyle", cwd))
	paths = append(paths, fmt.Sprintf("%s/.richstyle.yaml", cwd))
	paths = append(paths, fmt.Sprintf("%s/.richstyle.yml", cwd))

	if os.Getenv("RICHGO_LOCAL") != "1" {
		gopath := os.Getenv("GOPATH")
		if gopath != "" {
			paths = append(paths, fmt.Sprintf("%s/.richstyle", gopath))
			paths = append(paths, fmt.Sprintf("%s/.richstyle.yaml", gopath))
			paths = append(paths, fmt.Sprintf("%s/.richstyle.yml", gopath))
		}
		goroot := os.Getenv("GOROOT")
		if goroot != "" {
			paths = append(paths, fmt.Sprintf("%s/.richstyle", goroot))
			paths = append(paths, fmt.Sprintf("%s/.richstyle.yaml", goroot))
			paths = append(paths, fmt.Sprintf("%s/.richstyle.yml", goroot))
		}
		home, _ := os.UserHomeDir()
		if home != "" {
			paths = append(paths, fmt.Sprintf("%s/.richstyle", home))
			paths = append(paths, fmt.Sprintf("%s/.richstyle.yaml", home))
			paths = append(paths, fmt.Sprintf("%s/.richstyle.yml", home))
		}
	}

	for _, path := range paths {
		if data, err := os.ReadFile(path); err == nil {
			var overlay Config
			if err := yaml.Unmarshal(data, &overlay); err == nil {
				cfg = mergeConfig(cfg, overlay)
			}
		}
	}
	return cfg
}

var (
	reRun   = regexp.MustCompile(`^=== RUN\s+(Test|Benchmark|Example)?(.*)`)
	rePass  = regexp.MustCompile(`^--- PASS:\s+(Test|Benchmark|Example)?(.*?)\s*(\(.*\))?$`)
	reFail  = regexp.MustCompile(`^--- FAIL:\s+(Test|Benchmark|Example)?(.*?)\s*(\(.*\))?$`)
	reSkip  = regexp.MustCompile(`^--- SKIP:\s+(Test|Benchmark|Example)?(.*?)\s*(\(.*\))?$`)
	reBuild = regexp.MustCompile(`^#\s+(.*)`)
	reOk    = regexp.MustCompile(`^ok\s+(.*?)\s+([0-9.]+)s(\s+coverage:\s+([0-9.]+)% of statements)?`)
	reFailPkg = regexp.MustCompile(`^FAIL\t(.*?)\s+([0-9.]+)s`)
	reNoTest = regexp.MustCompile(`^\?\s+(.*?)\s+\[no test files\]`)
	reCover = regexp.MustCompile(`^coverage:\s+([0-9.]+)% of statements`)
	reFileLine = regexp.MustCompile(`([\w/.-]+\.go):(\d+)(:(\d+))?`)
)

func runFilter() {
	cfg := loadConfig()
	scanner := bufio.NewScanner(os.Stdin)

	forceColor := os.Getenv("RICHGO_FORCE_COLOR") == "1"
	useColor := forceColor // Simplification: in real richgo it checks TTY

	var currentStyle Style
	inBuild := false

	for scanner.Scan() {
		line := scanner.Text()

		// Apply removals
		skipLine := false
		for _, rem := range cfg.Removals {
			r := regexp.MustCompile(rem)
			if r.MatchString(line) {
				line = r.ReplaceAllString(line, "")
				if line == "" {
					skipLine = true
					break
				}
			}
		}
		if skipLine {
			continue
		}

		var outputLine string
		var label string
		var content string
		var style Style
		matched := false

		if m := reRun.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "START"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name
			style = cfg.StartStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := rePass.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "PASS"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name + " " + m[3]
			style = cfg.PassStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reFail.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "FAIL"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name + " " + m[3]
			style = cfg.FailStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reSkip.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "SKIP"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name + " " + m[3]
			style = cfg.SkipStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reBuild.FindStringSubmatch(line); m != nil {
			label = "BUILD"
			content = m[1]
			style = cfg.BuildStyle
			currentStyle = style
			inBuild = true
			matched = true
		} else if line == "PASS" {
			if cfg.PassPackageStyle.Hide != nil && *cfg.PassPackageStyle.Hide {
				continue
			}
			outputLine = applyStyle("PASS", cfg.PassPackageStyle)
			fmt.Println(outputLine)
			continue
		} else if line == "FAIL" {
			if cfg.FailPackageStyle.Hide != nil && *cfg.FailPackageStyle.Hide {
				continue
			}
			outputLine = applyStyle("FAIL", cfg.FailPackageStyle)
			fmt.Println(outputLine)
			continue
		} else if m := reOk.FindStringSubmatch(line); m != nil {
			label = "PASS"
			pkg := m[1]
			coverage := m[3]
			content = pkg + coverage
			style = cfg.PassStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reFailPkg.FindStringSubmatch(line); m != nil {
			label = "FAIL"
			content = "\t" + m[1] + "\t" + m[2] + "s"
			style = cfg.FailStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reNoTest.FindStringSubmatch(line); m != nil {
			label = "SKIP"
			content = m[1] + "\t[no test files]"
			style = cfg.SkipStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reCover.FindStringSubmatch(line); m != nil {
			label = "COVER"
			percent, _ := strconv.ParseFloat(m[1], 64)
			bar := "["
			for i := 0; i < 10; i++ {
				if float64(i*10) < percent {
					bar += "#"
				} else {
					bar += "_"
				}
			}
			bar += "]"
			content = fmt.Sprintf("%.1f%% %s", percent, bar)
			if int(percent) >= cfg.CoverThreshold {
				style = cfg.CoveredStyle
			} else {
				style = cfg.UncoveredStyle
			}
			matched = true
		} else {
			content = line
			style = currentStyle
			if inBuild {
				style = cfg.BuildStyle
			}
		}

		if useColor {
			content = highlightFileLine(content, cfg)
		}

		if matched {
			fmt.Println(formatLine(label, content, style, cfg, useColor))
		} else {
			fmt.Println(formatLine("", content, style, cfg, useColor))
		}
	}
}

func formatLine(label, content string, style Style, cfg Config, useColor bool) string {
	if cfg.LabelType == "none" {
		if useColor {
			return applyStyle(content, style)
		}
		return content
	}

	labelStr := ""
	if cfg.LabelType == "short" {
		switch label {
		case "BUILD":
			labelStr = "!!"
		case "START":
			labelStr = ">"
		case "PASS":
			labelStr = "o"
		case "FAIL":
			labelStr = "x"
		case "SKIP":
			labelStr = "-"
		case "COVER":
			labelStr = "%"
		default:
			labelStr = ""
		}
		labelStr = fmt.Sprintf("%-2s ", labelStr)
	} else { // long
		switch label {
		case "BUILD":
			labelStr = "BUILD|"
		case "START":
			labelStr = "START|"
		case "PASS":
			labelStr = "PASS |"
		case "FAIL":
			labelStr = "FAIL |"
		case "SKIP":
			labelStr = "SKIP |"
		case "COVER":
			labelStr = "COVER|"
		default:
			labelStr = "     |"
		}
		labelStr = labelStr + " "
	}

	if useColor {
		return applyStyle(labelStr+content, style)
	}
	return labelStr + content
}

func highlightFileLine(content string, cfg Config) string {
	return reFileLine.ReplaceAllStringFunc(content, func(m string) string {
		parts := reFileLine.FindStringSubmatch(m)
		file := parts[1]
		line := m[len(file):]
		return applyStyle(file, cfg.FileStyle) + applyStyle(line, cfg.LineStyle)
	})
}

func runTest(args []string) {
	cmd := exec.Command("go", append([]string{"test"}, args...)...)
	stdout, _ := cmd.StdoutPipe()
	stderr, _ := cmd.StderrPipe()
	cmd.Start()

	go func() {
		filterPipe(stdout)
	}()
	go func() {
		filterPipe(stderr)
	}()

	err := cmd.Wait()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}

func filterPipe(r io.Reader) {
	// Re-implementing filter logic for the pipe
	// For simplicity, just call a function that processes the stream
	// This is slightly tricky because we need to share state (currentStyle, inBuild) 
	// but the original richgo seems to process them line by line from combined output.
	// Actually, go test -v output is usually line-buffered.

	// For this exercise, I'll just use a scanner on a combined reader or something.
	// But let's just make runFilter take an input reader.
	processStream(r)
}

func processStream(r io.Reader) {
	// Re-implementation of runFilter logic but for a generic reader
	cfg := loadConfig()
	scanner := bufio.NewScanner(r)
	forceColor := os.Getenv("RICHGO_FORCE_COLOR") == "1"
	useColor := forceColor
	var currentStyle Style
	inBuild := false

	for scanner.Scan() {
		line := scanner.Text()

		skipLine := false
		for _, rem := range cfg.Removals {
			r := regexp.MustCompile(rem)
			if r.MatchString(line) {
				line = r.ReplaceAllString(line, "")
				if line == "" {
					skipLine = true
					break
				}
			}
		}
		if skipLine {
			continue
		}

		var label string
		var content string
		var style Style
		matched := false

		if m := reRun.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "START"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name
			style = cfg.StartStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := rePass.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "PASS"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name + " " + m[3]
			style = cfg.PassStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reFail.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "FAIL"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name + " " + m[3]
			style = cfg.FailStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reSkip.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "SKIP"
			name := m[2]
			if cfg.LeaveTestPrefix {
				name = m[1] + name
			}
			content = name + " " + m[3]
			style = cfg.SkipStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reBuild.FindStringSubmatch(line); m != nil {
			label = "BUILD"
			content = m[1]
			style = cfg.BuildStyle
			currentStyle = style
			inBuild = true
			matched = true
		} else if line == "PASS" {
			if cfg.PassPackageStyle.Hide == nil || !*cfg.PassPackageStyle.Hide {
				fmt.Println(applyStyle("PASS", cfg.PassPackageStyle))
			}
			continue
		} else if line == "FAIL" {
			if cfg.FailPackageStyle.Hide == nil || !*cfg.FailPackageStyle.Hide {
				fmt.Println(applyStyle("FAIL", cfg.FailPackageStyle))
			}
			continue
		} else if m := reOk.FindStringSubmatch(line); m != nil {
			label = "PASS"
			pkg := m[1]
			coverage := m[3]
			content = pkg + coverage
			style = cfg.PassStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reFailPkg.FindStringSubmatch(line); m != nil {
			label = "FAIL"
			content = "\t" + m[1] + "\t" + m[2] + "s"
			style = cfg.FailStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reNoTest.FindStringSubmatch(line); m != nil {
			label = "SKIP"
			content = m[1] + "\t[no test files]"
			style = cfg.SkipStyle
			currentStyle = style
			inBuild = false
			matched = true
		} else if m := reCover.FindStringSubmatch(line); m != nil {
			label = "COVER"
			percent, _ := strconv.ParseFloat(m[1], 64)
			bar := "["
			for i := 0; i < 10; i++ {
				if float64(i*10) < percent {
					bar += "#"
				} else {
					bar += "_"
				}
			}
			bar += "]"
			content = fmt.Sprintf("%.1f%% %s", percent, bar)
			if int(percent) >= cfg.CoverThreshold {
				style = cfg.CoveredStyle
			} else {
				style = cfg.UncoveredStyle
			}
			matched = true
		} else {
			content = line
			style = currentStyle
			if inBuild {
				style = cfg.BuildStyle
			}
		}

		if useColor {
