func ptr[T any](v T) *T {
	return &v
}

func parseBool(s string) *bool {
	s = strings.TrimSpace(s)
	if s == "true" {
		return ptr(true)
	} else if s == "false" {
		return ptr(false)
	}
	return nil
}

func parseYAML(data []byte, cfg *Config) {
	lines := strings.Split(string(data), "\n")
	var currentStyle *Style
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.Contains(line, ":") {
			parts := strings.SplitN(line, ":", 2)
			key := strings.TrimSpace(parts[0])
			val := strings.TrimSpace(parts[1])

			if val == "" {
				switch key {
				case "buildStyle": currentStyle = &cfg.BuildStyle
				case "startStyle": currentStyle = &cfg.StartStyle
				case "passStyle": currentStyle = &cfg.PassStyle
				case "failStyle": currentStyle = &cfg.FailStyle
				case "skipStyle": currentStyle = &cfg.SkipStyle
				case "fileStyle": currentStyle = &cfg.FileStyle
				case "lineStyle": currentStyle = &cfg.LineStyle
				case "passPackageStyle": currentStyle = &cfg.PassPackageStyle
				case "failPackageStyle": currentStyle = &cfg.FailPackageStyle
				case "coveredStyle": currentStyle = &cfg.CoveredStyle
				case "uncoveredStyle": currentStyle = &cfg.UncoveredStyle
				default: currentStyle = nil
				}
				continue
			}

			if currentStyle != nil {
				switch key {
				case "hide": currentStyle.Hide = parseBool(val)
				case "bold": currentStyle.Bold = parseBool(val)
				case "faint": currentStyle.Faint = parseBool(val)
				case "italic": currentStyle.Italic = parseBool(val)
				case "underline": currentStyle.Underline = parseBool(val)
				case "blinkSlow": currentStyle.BlinkSlow = parseBool(val)
				case "blinkRapid": currentStyle.BlinkRapid = parseBool(val)
				case "inverse": currentStyle.Inverse = parseBool(val)
				case "conceal": currentStyle.Conceal = parseBool(val)
				case "crossOut": currentStyle.CrossOut = parseBool(val)
				case "frame": currentStyle.Frame = parseBool(val)
				case "encircle": currentStyle.Encircle = parseBool(val)
				case "overline": currentStyle.Overline = parseBool(val)
				case "foreground": currentStyle.Foreground = strings.Trim(val, `"'`)
				case "background": currentStyle.Background = strings.Trim(val, `"'`)
				}
			} else {
				switch key {
				case "labelType": cfg.LabelType = strings.Trim(val, `"'`)
				case "coverThreshold": cfg.CoverThreshold, _ = strconv.Atoi(val)
				case "leaveTestPrefix": if b := parseBool(val); b != nil { cfg.LeaveTestPrefix = *b }
				}
			}
		} else if strings.HasPrefix(line, "-") {
			val := strings.TrimSpace(line[1:])
			cfg.Removals = append(cfg.Removals, strings.Trim(val, `"'`))
		}
	}
}

func colorToAnsi(color string, isBackground bool) string {
	if color == "" {
		return ""
	}
	offset := 0
	if isBackground {
		offset = 10
	}

	switch strings.ToLower(color) {
	case "black": return fmt.Sprintf("%d", 30+offset)
	case "red": return fmt.Sprintf("%d", 31+offset)
	case "green": return fmt.Sprintf("%d", 32+offset)
	case "yellow": return fmt.Sprintf("%d", 33+offset)
	case "blue": return fmt.Sprintf("%d", 34+offset)
	case "magenta": return fmt.Sprintf("%d", 35+offset)
	case "cyan": return fmt.Sprintf("%d", 36+offset)
	case "white": return fmt.Sprintf("%d", 37+offset)
	case "lightblack": return fmt.Sprintf("%d", 90+offset)
	case "lightred": return fmt.Sprintf("%d", 91+offset)
	case "lightgreen": return fmt.Sprintf("%d", 92+offset)
	case "lightyellow": return fmt.Sprintf("%d", 93+offset)
	case "lightblue": return fmt.Sprintf("%d", 94+offset)
	case "lightmagenta": return fmt.Sprintf("%d", 95+offset)
	case "lightcyan": return fmt.Sprintf("%d", 96+offset)
	case "lightwhite": return fmt.Sprintf("%d", 97+offset)
	}

	if strings.HasPrefix(color, "#") {
		var r, g, b uint8
		if _, err := fmt.Sscanf(color, "#%02x%02x%02x", &r, &g, &b); err == nil {
			return fmt.Sprintf("%d;2;%d;%d;%d", 38+offset, r, g, b)
		}
	}

	if strings.HasPrefix(color, "rgb(") {
		var r, g, b int
		if _, err := fmt.Sscanf(color, "rgb(%d,%d,%d)", &r, &g, &b); err == nil {
			return fmt.Sprintf("%d;2;%d;%d;%d", 38+offset, r, g, b)
		}
	}

	return ""
}

func (s Style) ToAnsi() string {
	var parts []string
	if s.Bold != nil && *s.Bold { parts = append(parts, "1") }
	if s.Faint != nil && *s.Faint { parts = append(parts, "2") }
	if s.Italic != nil && *s.Italic { parts = append(parts, "3") }
	if s.Underline != nil && *s.Underline { parts = append(parts, "4") }
	if s.BlinkSlow != nil && *s.BlinkSlow { parts = append(parts, "5") }
	if s.BlinkRapid != nil && *s.BlinkRapid { parts = append(parts, "6") }
	if s.Inverse != nil && *s.Inverse { parts = append(parts, "7") }
	if s.Conceal != nil && *s.Conceal { parts = append(parts, "8") }
	if s.CrossOut != nil && *s.CrossOut { parts = append(parts, "9") }
	if s.Frame != nil && *s.Frame { parts = append(parts, "51") }
	if s.Encircle != nil && *s.Encircle { parts = append(parts, "52") }
	if s.Overline != nil && *s.Overline { parts = append(parts, "53") }

	if fg := colorToAnsi(s.Foreground, false); fg != "" { parts = append(parts, fg) }
	if bg := colorToAnsi(s.Background, true); bg != "" { parts = append(parts, bg) }

	if len(parts) == 0 { return "" }
	return "\x1b[" + strings.Join(parts, ";") + "m"
}

func applyStyle(text string, style Style) string {
	ansi := style.ToAnsi()
	if ansi == "" { return text }
	return ansi + text + "\x1b[0m"
}

var (
	reRun   = regexp.MustCompile(`^=== RUN\s+(Test|Benchmark|Example)?(.*)`)
	rePass  = regexp.MustCompile(`^--- PASS:\s+(Test|Benchmark|Example)?(.*?)\s*(\(.*\))?$`)
	reFail  = regexp.MustCompile(`^--- FAIL:\s+(Test|Benchmark|Example)?(.*?)\s*(\(.*\))?$`)
	reSkip  = regexp.MustCompile(`^--- SKIP:\s+(Test|Benchmark|Example)?(.*?)\s*(\(.*\))?$`)
	reBuild = regexp.MustCompile(`^#\s+(.*)`)
	reOk    = regexp.MustCompile(`^ok\s+(.*?)\s+([0-9.]+)s(\s+coverage:\s+([0-9.]+)% of statements)?`)
	reFailPkg = regexp.MustCompile(`^FAIL\t(.*?)\s+([0-9.]+)s`)
	reNoTest = regexp.MustCompile(`^\?\s+(.*?)\s+\[no test files\]`)
	reCover = regexp.MustCompile(`^coverage:\s+([0-9.]+)% of statements`)
	reFileLine = regexp.MustCompile(`([\w/.-]+\.go):(\d+)(:(\d+))?`)
)

func main() {
	if len(os.Args) > 1 && os.Args[1] == "testfilter" {
		processStream(os.Stdin)
		return
	}

	if len(os.Args) > 1 && os.Args[1] == "test" {
		runTest(os.Args[2:])
		return
	}

	// Default: delegate to go
	cmd := exec.Command("go", os.Args[1:]...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}

func loadConfig() Config {
	cfg := defaultStyle()
	paths := []string{}
	cwd, _ := os.Getwd()
	paths = append(paths, fmt.Sprintf("%s/.richstyle", cwd), fmt.Sprintf("%s/.richstyle.yaml", cwd), fmt.Sprintf("%s/.richstyle.yml", cwd))
	if os.Getenv("RICHGO_LOCAL") != "1" {
		if gopath := os.Getenv("GOPATH"); gopath != "" {
			paths = append(paths, fmt.Sprintf("%s/.richstyle", gopath), fmt.Sprintf("%s/.richstyle.yaml", gopath), fmt.Sprintf("%s/.richstyle.yml", gopath))
		}
		if home, _ := os.UserHomeDir(); home != "" {
			paths = append(paths, fmt.Sprintf("%s/.richstyle", home), fmt.Sprintf("%s/.richstyle.yaml", home), fmt.Sprintf("%s/.richstyle.yml", home))
		}
	}

	for _, path := range paths {
		if data, err := os.ReadFile(path); err == nil {
			parseYAML(data, &cfg)
		}
	}
	return cfg
}

func processStream(r io.Reader) {
	cfg := loadConfig()
	scanner := bufio.NewScanner(r)
	useColor := os.Getenv("RICHGO_FORCE_COLOR") == "1"
	var currentStyle Style
	inBuild := false

	for scanner.Scan() {
		line := scanner.Text()

		skipLine := false
		for _, rem := range cfg.Removals {
			r := regexp.MustCompile(rem)
			if r.MatchString(line) {
				line = r.ReplaceAllString(line, "")
				if line == "" {
					skipLine = true
					break
				}
			}
		}
		if skipLine { continue }

		var label string
		var content string
		var style Style
		matched := false

		if m := reRun.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "START"; name := m[2]
			if cfg.LeaveTestPrefix { name = m[1] + name }
			content = name; style = cfg.StartStyle; currentStyle = style; inBuild = false; matched = true
		} else if m := rePass.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "PASS"; name := m[2]
			if cfg.LeaveTestPrefix { name = m[1] + name }
			content = name + " " + m[3]; style = cfg.PassStyle; currentStyle = style; inBuild = false; matched = true
		} else if m := reFail.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "FAIL"; name := m[2]
			if cfg.LeaveTestPrefix { name = m[1] + name }
			content = name + " " + m[3]; style = cfg.FailStyle; currentStyle = style; inBuild = false; matched = true
		} else if m := reSkip.FindStringSubmatch(line); m != nil && (m[1] == "Test" || m[1] == "") {
			label = "SKIP"; name := m[2]
			if cfg.LeaveTestPrefix { name = m[1] + name }
			content = name + " " + m[3]; style = cfg.SkipStyle; currentStyle = style; inBuild = false; matched = true
		} else if m := reBuild.FindStringSubmatch(line); m != nil {
			label = "BUILD"; content = m[1]; style = cfg.BuildStyle; currentStyle = style; inBuild = true; matched = true
		} else if line == "PASS" {
			if cfg.PassPackageStyle.Hide == nil || !*cfg.PassPackageStyle.Hide {
				fmt.Println(applyStyle("PASS", cfg.PassPackageStyle))
			}
			currentStyle = cfg.PassStyle; inBuild = false; continue
		} else if line == "FAIL" {
			if cfg.FailPackageStyle.Hide == nil || !*cfg.FailPackageStyle.Hide {
				fmt.Println(applyStyle("FAIL", cfg.FailPackageStyle))
			}
			currentStyle = cfg.FailStyle; inBuild = false; continue
		} else if m := reOk.FindStringSubmatch(line); m != nil {
			label = "PASS"; pkg := m[1]; coverage := m[3]; content = pkg + coverage; style = cfg.PassStyle; currentStyle = style; inBuild = false; matched = true
		} else if m := reFailPkg.FindStringSubmatch(line); m != nil {
			label = "FAIL"; content = "\t" + m[1] + "\t" + m[2] + "s"; style = cfg.FailStyle; currentStyle = style; inBuild = false; matched = true
		} else if m := reNoTest.FindStringSubmatch(line); m != nil {
			label = "SKIP"; content = m[1] + "\t[no test files]"; style = cfg.SkipStyle; currentStyle = style; inBuild = false; matched = true
		} else if m := reCover.FindStringSubmatch(line); m != nil {
			label = "COVER"; percent, _ := strconv.ParseFloat(m[1], 64); bar := "["
			for i := 0; i < 10; i++ {
				if float64(i*10) < percent { bar += "#" } else { bar += "_" }
			}
			bar += "]"; content = fmt.Sprintf("%.1f%% %s", percent, bar)
			if int(percent) >= cfg.CoverThreshold { style = cfg.CoveredStyle } else { style = cfg.UncoveredStyle }
			matched = true
		} else {
			content = line; style = currentStyle
			if inBuild { style = cfg.BuildStyle }
		}

		if useColor {
			content = highlightFileLine(content, cfg)
		}

		fmt.Println(formatLine(label, content, style, cfg, useColor))
	}
}

func formatLine(label, content string, style Style, cfg Config, useColor bool) string {
	if cfg.LabelType == "none" {
		if useColor { return applyStyle(content, style) }
		return content
	}

	labelStr := ""
	if cfg.LabelType == "short" {
		switch label {
		case "BUILD": labelStr = "!!"
		case "START": labelStr = ">"
		case "PASS": labelStr = "o"
		case "FAIL": labelStr = "x"
		case "SKIP": labelStr = "-"
		case "COVER": labelStr = "%"
		default: labelStr = ""
		}
		labelStr = fmt.Sprintf("%-2s ", labelStr)
	} else {
		switch label {
		case "BUILD": labelStr = "BUILD|"
		case "START": labelStr = "START|"
		case "PASS": labelStr = "PASS |"
		case "FAIL": labelStr = "FAIL |"
		case "SKIP": labelStr = "SKIP |"
		case "COVER": labelStr = "COVER|"
		default: labelStr = "     |"
		}
		labelStr = labelStr + " "
	}

	if useColor { return applyStyle(labelStr+content, style) }
	return labelStr + content
}

func highlightFileLine(content string, cfg Config) string {
	return reFileLine.ReplaceAllStringFunc(content, func(m string) string {
		parts := reFileLine.FindStringSubmatch(m)
		file := parts[1]
		line := m[len(file):]
		return applyStyle(file, cfg.FileStyle) + applyStyle(line, cfg.LineStyle)
	})
}

func runTest(args []string) {
	cmd := exec.Command("go", append([]string{"test"}, args...)...)
	pr, pw := io.Pipe()
	cmd.Stdout = pw
	cmd.Stderr = pw
	go func() { processStream(pr) }()
	err := cmd.Start()
	if err != nil { os.Exit(1) }
	err = cmd.Wait()
	pw.Close()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok { os.Exit(exitErr.ExitCode()) }
		os.Exit(1)
	}
}
